import { useState } from "react";

function LoansActions({ dispatch }) {
  const [withdrawalAmount, setWithdrawalAmount] = useState(0);
  const [depositAmount, setDepositAmount] = useState(0);
  return (
    <div>
      <h3>Loans Actions</h3>
      <div>
        <form>
          <label htmlFor="amount">Amount:</label>
          <input
            type="number"
            id="amount"
            name="amount"
            value={depositAmount}
            onChange={(e) => setDepositAmount(Number(e.target.value))}
          />
          <button
            type="submit"
            onClick={(e) => {
              e.preventDefault();
              dispatch({ type: "deposit", payload: depositAmount });
            }}
          >
            Submit
          </button>
        </form>
      </div>
      <div>
        <form>
          <label htmlFor="amount">Amount:</label>
          <input
            type="number"
            id="amount"
            name="amount"
            value={withdrawalAmount}
            onChange={(e) => setWithdrawalAmount(Number(e.target.value))}
          />
          <button
            type="submit"
            onClick={(e) => {
              e.preventDefault();
              dispatch({ type: "withdraw", payload: withdrawalAmount });
            }}
          >
            Submit
          </button>
        </form>
      </div>
    </div>
  );
}

export default LoansActions;
